/**
 * The interfaces between the parts of the captioning pipeline. FROZEN: several people build the
 * parts at the same time against these, so a change here needs agreement (write it in
 * `.team/chat.md`, do not edit this file yourself).
 *
 * Conventions (see types.ts for the time rules):
 *  - Audio is always 16 kHz, mono, Float32 in -1..1.
 *  - All times are integer milliseconds. Window-local time starts at 0 at the start of a packed window.
 *  - Every async call takes an AbortSignal and must reject with a `CaptionError` of code "aborted"
 *    when cancelled, promptly, without leaving a half-finished state behind.
 *  - Nothing here may send user audio, text or file names over the network. Only the model loader
 *    (model-loader.ts) touches the network, and only for pinned model files.
 */

import type { DownloadProgress } from "./model-loader";
import type { CaptionEvent, PackedWindow, SpeechInterval, Word } from "./types";

export const SAMPLE_RATE = 16_000;
/** The fixed input length of stock Whisper, in milliseconds and in samples. */
export const WINDOW_MS = 30_000;
export const WINDOW_SAMPLES = (WINDOW_MS / 1000) * SAMPLE_RATE;

export type CaptionLanguage = "hinglish" | "hindi" | "english";

export type CaptionErrorCode =
  | "aborted"
  | "unsupported-file" // container or codec the browser cannot decode, and no fallback worked
  | "no-audio" // the file has no audio track
  | "no-speech" // audio found, but the voice detector heard nothing
  | "model-download" // see ModelLoadError
  | "model-load" // the model downloaded but would not start (out of memory, no WebGPU and no fallback)
  | "device-lost" // the GPU went away mid-job and the fallback also failed
  | "interrupted" // the browser stopped the model without the visitor asking (GPU reset, out of memory, a killed worker)
  | "inference" // the model failed on a window
  | "export"
  | "internal";

export class CaptionError extends Error {
  constructor(
    readonly code: CaptionErrorCode,
    message: string,
    options?: { cause?: unknown },
  ) {
    super(message, options);
    this.name = "CaptionError";
  }
}

/** A run of consecutive audio samples starting `startMs` into the source. Chunks arrive in order and never overlap. */
export interface PcmChunk {
  startMs: number;
  samples: Float32Array;
}

// ---------------------------------------------------------------- audio

export interface AudioSource {
  /** Total duration in ms if the container says so, else null. */
  durationMs: number | null;
  /** Yields contiguous 16 kHz mono chunks in order. Stops cleanly on abort. */
  chunks(signal?: AbortSignal): AsyncIterable<PcmChunk>;
  /** Releases decoders and file handles. Safe to call twice. */
  close(): Promise<void>;
}

export interface AudioIngest {
  /** Opens the file. Rejects with CaptionError "unsupported-file" or "no-audio". Reads nothing into memory beyond what it decodes. */
  open(file: File, signal?: AbortSignal): Promise<AudioSource>;
}

// ---------------------------------------------------------------- voice detection

export interface VoiceDetector {
  /**
   * Feeds audio in order. Returns the speech intervals (global ms) that are now CLOSED, meaning
   * followed by enough silence to be sure they ended. An interval still open stays internal until
   * later audio closes it or `flush` is called.
   */
  push(chunk: PcmChunk, signal?: AbortSignal): Promise<SpeechInterval[]>;
  /** Closes any open interval at the end of the audio. */
  flush(): Promise<SpeechInterval[]>;
  /** Forgets all state so the detector can start a new file. */
  reset(): void;
  release(): Promise<void>;
}

// ---------------------------------------------------------------- speech model

/** Audio for one packed window: exactly WINDOW_SAMPLES samples, speech regions packed with silence between, zero padded at the end. */
export interface WindowAudio {
  window: PackedWindow;
  samples: Float32Array;
}

/** What the speech model heard in one window, before words are timed. */
export interface WindowTranscript {
  windowIndex: number;
  /** Decoded text split into words in speaking order. Punctuation stays attached to its word. */
  words: string[];
  /** The model's token ids for the same text, in order (the aligner may need them). */
  tokenIds: number[];
  /** Probability the model gave to "no speech" at the first step (0..1). */
  noSpeechProbability: number;
  /** Mean log-probability of the chosen tokens (<= 0). */
  averageLogProbability: number;
  /** How sure the model was of each word, 0..1, same length as `words`. Absent when it cannot be worked out. */
  wordConfidence?: number[];
  /** Where the model itself heard each word (window-local ms), same length as `words`. Absent when the model gives no timing. */
  wordTimes?: { startMs: number; endMs: number }[];
}

export interface EngineLoadOptions {
  signal?: AbortSignal;
  onDownload?: (progress: DownloadProgress) => void;
}

/**
 * Per-call decode bounds. Used by song mode to read a hard window with a tighter loop guard; a missing
 * field means the engine's own configured default.
 */
/**
 * One word of KNOWN text (the visitor's lyrics or script) placed on a window's audio by the
 * teacher-forced aligner. Times are window-local milliseconds and never past `usedMs`.
 */
export interface ForcedAlignWord {
  text: string;
  startMs: number;
  endMs: number;
  /** Mean per-token log-probability of this word under the teacher-forced pass (<= 0; more negative = less sure). */
  logProbability: number;
  /** 0..1: how concentrated the word's character attention is on the frames it was placed on. */
  sharpness: number;
}

export interface ForcedAlignResult {
  /** One entry per word of `text`, in order. */
  words: ForcedAlignWord[];
  /** The language token the pass used, for diagnostics ("en" / "hi"). */
  languageToken?: string;
}

export interface TranscribeBounds {
  /** Most new tokens per second of audio. */
  tokensPerSecond?: number;
  /** Stop when a run of `n` tokens repeats `times` times (the decoder keeps one copy of the run). */
  repetitionRules?: readonly { n: number; times: number }[];
  /** Silence put in front of a shifted second take; 0 disables the extra take for this call. */
  retryShiftMs?: number;
}

export interface SpeechEngine {
  /** A stable name, e.g. "whisper-swift-base-hinglish". Shown in the UI and stored in results. */
  readonly id: string;
  /** Downloads (through model-loader) and starts the model. Idempotent. */
  load(options?: EngineLoadOptions): Promise<void>;
  /**
   * `glossary` is names and special words the model should expect (given to it as a hint before it listens).
   * `music` asks for the language token tuned for sung Hindi. The pipeline sets it only when detection is "everything":
   * on the second read of a hard song window (the per-window token vote) and on every shifted rescue slice. Speech and
   * songs whose windows read cleanly never set it, so they are unchanged.
   */
  transcribe(input: WindowAudio, options: { language: CaptionLanguage; signal?: AbortSignal; glossary?: readonly string[]; music?: boolean; bounds?: TranscribeBounds }): Promise<WindowTranscript>;
  /**
   * Optional: places KNOWN text (lyrics or a script) on the window with one teacher-forced decoder pass,
   * reusing the encoder output of the immediately preceding `transcribe` on the same audio when the engine
   * can. Returns one entry per word of `text`, or `null` when the model cannot say (no attention, too long,
   * aborted, an engine that does not implement it). It never throws for those cases and never changes
   * `transcribe` results. Text is limited to 400 characters per call; callers chunk it.
   */
  alignText?(input: WindowAudio, text: string, options?: { language?: CaptionLanguage; signal?: AbortSignal }): Promise<ForcedAlignResult | null>;
  /** Frees GPU/WASM memory. After this `load` must work again. */
  release(): Promise<void>;
}

/** Gives each word of a transcript a start and end time inside the window (window-local ms). */
export interface WordAligner {
  readonly id: string;
  load(options?: EngineLoadOptions): Promise<void>;
  /**
   * Returns one Word per transcript word, in order, window-local, never past `input.window.usedMs`.
   * `confidence` reflects how well the audio supports that word.
   */
  align(input: WindowAudio, transcript: WindowTranscript, signal?: AbortSignal): Promise<Word[]>;
  release(): Promise<void>;
}

// ---------------------------------------------------------------- pipeline

export type PipelineStage = "reading-audio" | "finding-speech" | "loading-model" | "transcribing" | "aligning" | "finishing";

export interface PipelineProgress {
  stage: PipelineStage;
  /** 0..1 for the whole job. Monotonic: it never goes backwards. */
  fraction: number;
  /** Plain words for the UI, e.g. "Transcribing 2 of 5". */
  message: string;
  /** Set while the model is downloading. */
  download?: DownloadProgress;
}

export interface PipelineOptions {
  language: CaptionLanguage;
  signal?: AbortSignal;
  /**
   * Which audio is read: "speech" only the stretches the voice detector calls speech; "everything" the whole file except
   * stretches the vocal-activity detector is confident are instrumental, so songs and music where a voice detector misses
   * singing are still read. The pipeline treats a missing value as "speech"; the Auto captions page passes "everything".
   */
  detection?: "speech" | "everything";
  /** Names and special words the speech model should expect (a hint, not a guarantee). */
  glossary?: readonly string[];
  /**
   * The visitor's lyrics or script (optional). When present the normal transcription still runs, then the
   * words of this text are placed on the audio by forced alignment instead of being guessed. It never
   * leaves the device. See pipeline/lyrics.ts.
   */
  lyrics?: string;
  onProgress?: (progress: PipelineProgress) => void;
  /** Called each time a window is finished, with every caption event so far. Lets the UI show the first captions early. */
  onPartial?: (events: CaptionEvent[], words: Word[]) => void;
}

export interface LyricsStats {
  /** How many non-empty lines the visitor pasted. */
  lines: number;
  /** Lyric words placed on the audio (including uncertain ones). */
  placed: number;
  /** Placed words whose evidence was weak; they are shown as uncertain. */
  uncertain: number;
  /** Words of the pasted text that never found audio support. */
  unmatched: number;
  /** Lines that never found audio support, in the visitor's spelling (bounded for the panel). */
  unmatchedLines: string[];
  /** True when this tier has no forced aligner (Draft), so the text could not be used at all. */
  unsupported?: boolean;
  /**
   * Placed words whose timing was predicted (anchors + vocal activity + syllable share) rather than
   * verified by the teacher-forced pass. On a tier without an aligner every placed word is approximate.
   */
  approximate?: number;
  /**
   * Diagnostics (no UI): words the aligner returned across every `alignText` call of this job. `returned - accepted`
   * is what the end guard, the padding and the second-pass overlap filter refused, so a user report of "0 placed"
   * can be told apart from "the aligner returned nothing".
   */
  returned?: number;
  /** Diagnostics: words that passed the acceptance guards (and the second-pass overlap filter) and were placed. */
  accepted?: number;
  /** Diagnostics: audio windows where the aligner returned nothing (null, empty, or a thrown error). */
  nullWindows?: number;
  /** Diagnostics: how many `alignText` calls were made (at most 2 per audio window). */
  passes?: number;
  /**
   * Diagnostics: placed words whose timing was borrowed from a heard word the transcript agreed with (see
   * `alignLyrics`): the words are the visitor's, the timing is the transcript's, so pasting lyrics never makes the
   * timing worse than free transcription where the two agree.
   */
  timingBorrowed?: number;
}

export interface PipelineStats {
  /** Seconds of audio found in the file. */
  audioSeconds: number;
  /** Seconds of speech the detector found. */
  speechSeconds: number;
  windows: number;
  /** Windows the hallucination gate flagged. */
  flaggedWindows: number;
  /** Words dropped as invented (outside speech, in padding, etc). */
  droppedWords: number;
  /**
   * Song mode only: words copied from a repeated section of the song because the other occurrence was
   * unreadable. They are marked `inferred` and carry a low confidence.
   */
  inferredWords?: number;
  /** Only set when the visitor pasted lyrics or a script: how much of it was placed on the audio. */
  lyrics?: LyricsStats;
  /** Wall-clock milliseconds per stage. */
  stageMs: Partial<Record<PipelineStage, number>>;
  engineId: string;
  alignerId: string;
}

export interface CaptionResult {
  words: Word[];
  events: CaptionEvent[];
  stats: PipelineStats;
  /** Stretches of detected speech that ended up with no word, for the UI to flag. */
  uncoveredSpeech: SpeechInterval[];
}

export interface PipelineDeps {
  ingest: AudioIngest;
  vad: VoiceDetector;
  engine: SpeechEngine;
  aligner: WordAligner;
  /** For tests. Defaults to performance.now. */
  now?: () => number;
}

export interface CaptionPipeline {
  run(file: File, options: PipelineOptions): Promise<CaptionResult>;
  /**
   * Starts the speech model without any audio, so the first job begins sooner. Only call it when the model files are already saved
   * (it would download them otherwise). A no-op while a job runs or after dispose; never rejects.
   */
  prewarm?(signal?: AbortSignal): Promise<void>;
  /**
   * Frees the models' memory but keeps the pipeline usable: the next `run` starts them again. A no-op while a job runs or after
   * dispose; never rejects. (`dispose` is the permanent version.)
   */
  unloadModels?(): Promise<void>;
  /** Frees every model. */
  dispose(): Promise<void>;
}

// ---------------------------------------------------------------- export

export interface CaptionStyle {
  id: "clean" | "shorts" | "bold";
  fontFamily: string;
  /** Font size as a fraction of the video height. */
  fontScale: number;
  textColor: string;
  /** Colour of the word being spoken (karaoke). */
  activeColor: string;
  /** Pill or outline behind the text. */
  background: "none" | "pill" | "outline";
  /** "bottom" or "middle": where the block sits. */
  position: "bottom" | "middle";
}

export interface BurnInOptions {
  file: File;
  events: CaptionEvent[];
  style: CaptionStyle;
  signal?: AbortSignal;
  onProgress?: (fraction: number) => void;
}

export interface BurnInExporter {
  /** Whether this browser can burn captions in (WebCodecs video encode). Cheap, no side effects. */
  isSupported(): Promise<boolean>;
  /** Returns the captioned MP4. Preserves the source frame timestamps exactly (variable frame rate included). */
  export(options: BurnInOptions): Promise<Blob>;
}

// ---------------------------------------------------------------- the UI's view of a job

export type CaptionJobState =
  | { phase: "idle" }
  | { phase: "needs-consent"; download: { totalBytes: number; hosts: string[]; fileCount: number } }
  | { phase: "running"; progress: PipelineProgress; events: CaptionEvent[] }
  | { phase: "done"; result: CaptionResult }
  | { phase: "failed"; error: CaptionError }
  | { phase: "cancelled" };
